TypeScript// src/TimeTravelView.tsx (Replace lines 60-70)
import { useState } from 'react';

interface PatientData { gender: 'male' | 'female'; age: number; totalChol: number; hdl: number; sbp: number; onHtMed: boolean; smoker: boolean; diabetic: boolean; vascular: boolean; }
// Exact Framingham (2008) from D'Agostino et al. via GitHub

const calculateFramingham = (data: PatientData) => {
const lnAge = Math.log(data.age);
const lnTotalChol = Math.log(data.totalChol);
const lnHdl = Math.log(data.hdl);
const treatedSbp = data.onHtMed ? Math.log(data.sbp) * 1.797 : Math.log(data.sbp) * 1.764; // Gender-neutral approx
const smokerPoints = data.smoker ? 0.6545 : 0;
const diabeticPoints = data.diabetic ? 0.5737 : 0;
let points = 3.06117 * lnAge + 1.12370 * lnTotalChol - 0.93263 * lnHdl + treatedSbp + smokerPoints + diabeticPoints; // Simplified male; adjust for female

if (data.gender === 'female') points -= 2.32888; // Base adjustment
const risk = 1 - Math.pow(0.88936, Math.exp(points - 23.9802)); // 10-year CHD

return risk * 100;
};
// In component:

const [data, setData] = useState<PatientData>({ /* defaults */ });
const risk = calculateFramingham(data);
<p>10-Year CHD Risk: {risk.toFixed(1)}% {risk > 20 ? '—Brutal truth: High risk, change habits or face the reaper!' : ''}</p>
// Branching: What-if statin (reduce chol 20%)

const statinData = { ...data, totalChol: data.totalChol * 0.8 };
const statinRisk = calculateFramingham(statinData);
<p>With Statin: {statinRisk.toFixed(1)}% (Drop: {(risk - statinRisk).toFixed(1)}%—Smart move, survivor!)</p>
